// Independent local UI prototype. DEMO content is synthetic and never persisted to a book.
let treeMode='plan', volumeFocus=0, mainFocus='all', interweave=false;
const volumeNames=['破铺起家','工坊成形','边境新路','遗迹深处','封锁之下','众人的选择','预言裂缝','共赴终局'];
const chainNames=[['保住修理铺','接下第一笔订单','寻找旧零件的来处','机甲第一次拒绝'],['验证匠人工艺','兑现订单承诺','追查商会密信','重新约定伙伴关系'],['建立边境互市','交换遗迹线索','护送共同的货物','争取机甲同行资格'],['修复遗迹入口','核对残缺记录','救出被困的伙伴','带回关键证据'],['应对材料封锁','寻找匿名寄信人','组织工坊自救','公开合作条件'],['面对伙伴分歧','重建共同目标','机甲提出自己的方案','联手验证古代记录'],['比对预言版本','确认错误的来源','准备应对天劫','机甲选择承担什么'],['集结各方力量','执行共同的工程','完成自主选择','兑现共存的未来']];
const memberships=[['001','004','018','013'],['007','004','012','013'],['009','018','009','013'],['018','021','013','021'],['012','012','007','009'],['007','009','013','021'],['021','021','018','013'],['009','018','013','021']];
const treeChains=memberships.flatMap((ids,v)=>ids.map((id,k)=>({id:`${v+1}-${k+1}`,volume:v+1,index:k,lineIds:[id,...(v===0&&k===2?['004']:[])],title:chainNames[v][k],actual:v===0||v===1&&k<3})));
const ties=[{from:'1-2',to:'1-3',kind:'承接',text:'订单留下的异常零件，成为追查遗迹的起点。',actual:true},{from:'1-3',to:'4-1',kind:'承接',text:'零件线索指向遗迹入口；后续调查才有明确去处。',actual:false},{from:'2-3',to:'5-2',kind:'影响',text:'商会密信尚未解答，后续封锁让寄信人的动机更重要。',actual:false},{from:'6-3',to:'8-3',kind:'承接',text:'机甲开始提出方案，最终由它决定是否承担终局行动。',actual:false}];
const inMode=c=>treeMode==='plan'||c.actual;
const inMain=c=>mainFocus==='all'||c.lineIds.some(id=>D.tree.find(l=>l.id===id)?.main===mainFocus);
const availableChains=()=>treeChains.filter(c=>inMode(c)&&inMain(c)&&(!volumeFocus||c.volume===volumeFocus));
const visibleLines=()=>D.tree.filter(l=>(l.id+l.title+l.summary).includes(query)&&(filter==='all'||filter==='open'&&!l.closed||filter==='leaf'&&l.seeds.length)&&availableChains().some(c=>c.lineIds.includes(l.id)));
function badge(l,x,y){return `<g class="tree-node" role="button" tabindex="0" data-node="${l.id}" aria-label="故事线${l.id}，${esc(l.title)}" aria-pressed="${selected===l.id}" transform="translate(${x} ${y})"><circle r="27" fill="transparent"/><rect class="ring" x="-25" y="-18" width="50" height="36" rx="18"/><text text-anchor="middle" dy="5">${l.id}</text>${treeMode==='actual'&&l.closed?'<circle cx="26" cy="-21" r="8" fill="#c45b42"/>':''}${treeMode==='actual'&&l.seeds.length?'<path d="M20 23Q45 1 42 22Q32 34 20 23" fill="#71964e"/>':''}</g>`}
function transform(){const g=$('#tree-group');if(g)g.setAttribute('transform',`translate(${dx} ${dy}) translate(450 425) scale(${zoom}) translate(-450 -425)`)}
function treeDrawing(){const selectedVolumes=new Set(treeChains.filter(c=>inMode(c)&&c.lineIds.includes(selected)).map(c=>c.volume));
 if(volumeFocus){const cs=availableChains();return `<svg viewBox="0 0 640 600" aria-label="本卷的链与故事线"><g id="tree-group"><path fill="#69846b" d="M50 580Q116 420 90 70L106 70Q151 360 107 580Z"/><path d="M95 90Q175 55 250 50" class="volume-limb"/>${cs.map(c=>{const y=130+c.index*115;const ls=c.lineIds.map(id=>D.tree.find(l=>l.id===id));return `<path d="M108 ${y+70}Q230 ${y+15} 310 ${y}T505 ${y-30}" class="chain-limb ${c.lineIds.includes(selected)?'lit':''}" data-chain="${c.id}"/><g role="button" tabindex="0" data-chain="${c.id}" aria-label="第${c.index+1}链，${esc(c.title)}"><circle cx="290" cy="${y+3}" r="23" fill="#ecf0df" stroke="#b7a16d"/><text x="290" y="${y+8}" text-anchor="middle" class="chain-number">${c.index+1}</text></g>${ls.map((l,i)=>badge(l,420+i*85,y-25)).join('')}`}).join('')}${!cs.length?'<circle cx="320" cy="280" r="6" fill="#b5c2b0"/>':''}</g></svg>`}
 return `<svg viewBox="0 0 900 850" aria-label="全书时光树，选择卷枝展开故事链"><g id="tree-group"><ellipse cx="450" cy="790" rx="130" ry="17" fill="#d9e1c8" opacity=".65"/><path fill="#678168" d="M376 798Q426 738 416 652Q400 520 429 393Q445 254 447 71L457 71Q479 272 473 407Q459 552 483 665Q478 742 526 798Q478 782 451 758Q421 783 376 798Z"/><path d="M451 755Q453 587 449 460T453 92" stroke="#b2bc98" stroke-width="3" fill="none" opacity=".6"/>${volumeNames.map((name,i)=>{const v=i+1,side=i%2?-1:1,y=690-i*70,tipX=450+side*(250+(i%3)*12),tipY=y-105;const cs=treeChains.filter(c=>c.volume===v&&inMode(c));const muted=!cs.some(inMain);const highlighted=selectedVolumes.has(v);return `<g class="volume-group ${muted?'dim':''}" data-volume="${v}" role="button" tabindex="0" aria-label="第${v}卷 ${name}，${cs.length}条链"><path d="M450 ${y+36}Q${450+side*90} ${y+18} ${450+side*150} ${y-48}T${tipX} ${tipY}" fill="none" stroke="${highlighted?'#567e52':'#849b73'}" stroke-width="${29-i*2}" stroke-linecap="round"/>${[0,1,2,3].map(k=>{const sx=450+side*(92+k*42),sy=y-8-k*27,tx=sx+side*(23+k*2),ty=sy-59;return `<path d="M${sx} ${sy}Q${tx-side*12} ${ty+18} ${tx} ${ty}" class="twig" style="opacity:${cs[k]?1:.2}"/>`}).join('')}<circle cx="${tipX}" cy="${tipY}" r="29" fill="${highlighted?'#426849':'#fffdf4'}" stroke="#b39b63" stroke-width="2"/><text x="${tipX}" y="${tipY+6}" text-anchor="middle" fill="${highlighted?'white':'#526847'}" class="volume-number">${String(v).padStart(2,'0')}</text></g>`}).join('')}</g></svg>`}
function showLine(id,open=false){selected=id;if(!open){renderTree();return}const l=D.tree.find(x=>x.id===id);if(!l)return;const cs=treeChains.filter(c=>inMode(c)&&c.lineIds.includes(id));dialog(`${l.id} · ${l.title}`,`<span class="pill">${treeMode==='plan'?'规划候选':l.closed?'已收束':'推进中'}</span><p>${treeMode==='plan'?'以下为预计经过的卷与链，尚不代表正文发生。':esc(l.summary)}</p><div class="path-stops">${cs.map(c=>`<button data-jump="${c.volume}">第${c.volume}卷 · 链${c.index+1}</button>`).join('')}</div>${treeMode==='actual'?l.seeds.map(s=>`<div class="leaf-detail">🍃 <b>${esc(s[0])}</b><p>${esc(s[1])}</p></div>`).join(''):''}`);document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{$('#detail').close();volumeFocus=+b.dataset.jump;query='';filter='all';renderTree()})}
function showChain(id){const c=treeChains.find(x=>x.id===id);const edges=ties.filter(t=>(t.from===id||t.to===id)&&(treeMode==='plan'||t.actual));dialog(`第${c.volume}卷 · 链${c.index+1} · ${c.title}`,`<p>涉及故事线：${c.lineIds.join('、')}</p><span class="pill">${treeMode==='plan'?'规划候选':'正文轨迹演示'}</span>${edges.map(t=>`<div class="leaf-detail"><b>${t.kind} · ${t.from} → ${t.to}</b><p>${t.text}</p></div>`).join('')||'<p>本例未标注与其他链的直接依赖。</p>'}<p class="sub">正式功能在这里展开章节与来源；当前没有真实章节数据。</p>`)}
function renderTree(){const lines=visibleLines(),cs=availableChains(),selectedCs=treeChains.filter(c=>inMode(c)&&c.lineIds.includes(selected));const edges=ties.filter(t=>(treeMode==='plan'||t.actual)&&[t.from,t.to].some(id=>selectedCs.some(c=>c.id===id))&&(!volumeFocus||[t.from,t.to].some(id=>id.startsWith(volumeFocus+'-'))));
 $('#content').innerHTML=`<div class="row"><div><h1>让故事，长成一棵大树。</h1><p class="sub">${esc(D.book)}</p></div><div class="mode-tabs"><button data-mode="plan" aria-pressed="${treeMode==='plan'}">规划</button><button data-mode="actual" aria-pressed="${treeMode==='actual'}">正文</button></div></div><div class="tree-summary"><span>8 卷候选</span><span>${treeChains.filter(inMode).length} 条${treeMode==='plan'?'链样例':'已推进链样例'}</span><span>2 条主线 · 8 条故事线样例</span></div><div class="toolbar"><select id="volume" aria-label="查看卷"><option value="0">全树 · 8 卷</option>${volumeNames.map((n,i)=>`<option value="${i+1}">第${i+1}卷 · ${n}</option>`).join('')}</select><select id="main" aria-label="主线筛选"><option value="all">全部主线</option><option>机甲道路</option><option>机甲生命</option></select><button id="weave" aria-pressed="${interweave}">交织关系</button><button id="minus" aria-label="缩小树">−</button><button id="plus" aria-label="放大树">＋</button><button id="reset">回到全树</button></div><div class="tree-layout"><section><div class="canvas">${treeDrawing()}</div><div class="tree-legend"><span>粗干：全书</span><span>大枝：卷</span><span>小枝：链</span><span>卷内三位数：故事线编号</span>${treeMode==='actual'?'<span><i class="dot"></i>已收束</span><span><i class="leafmark"></i>伏笔未解</span>':''}</div><p class="sub">${volumeFocus?`第${volumeFocus}卷 · ${volumeNames[volumeFocus-1]} · ${cs.length} 条链；点击链序号查看交织。`:'点击卷号展开；高亮卷枝表示选中故事线经过的卷。'}${treeMode==='plan'?' 未来逐卷展开，不预先生成全部细节。':' 灰淡卷枝尚无本例正文进展。'}</p>${volumeFocus?`<div class="chain-sequence">${cs.map(c=>`<button data-chain="${c.id}"><b>链 ${c.index+1}</b> ${c.title}<small>故事线 ${c.lineIds.join(' / ')}</small></button>`).join('')||'<p>本卷尚无正文进展样例。可切换规划查看候选。</p>'}</div>`:''}${interweave?`<section class="weave-panel"><div class="row"><h3>故事线 ${selected} · 经过与交织</h3><span class="pill">${treeMode==='plan'?'预计路径':'已发生样例'}</span></div><div class="path-stops">${selectedCs.map(c=>`<button data-stop="${c.volume}">${c.volume}卷 · 链${c.index+1}</button>`).join('<span aria-hidden="true">→</span>')}</div>${edges.map(t=>`<article><b>${t.from.replace('-','卷 · 链')} → ${t.to.replace('-','卷 · 链')} · ${t.kind}</b><p>${t.text}</p></article>`).join('')||'<p class="sub">本例没有标注当前范围内的直接依赖，不因同卷就推定有因果关系。</p>'}</section>`:''}</section><aside class="panel number-list"><div class="row"><h3>故事线序列表</h3><button class="list-collapse" id="collapse">收起</button></div><input id="search" type="search" value="${esc(query)}" placeholder="查编号或故事名称" aria-label="查找故事线"><select id="filter" aria-label="筛选故事线"><option value="all">全部状态</option>${treeMode==='actual'?'<option value="open">未收束</option><option value="leaf">有待兑现伏笔</option>':''}</select><p class="sub">当前范围 ${lines.length} / 全部 ${D.tree.length} 条；编号跨卷保持不变。</p><div id="line-rows">${lines.map(l=>`<button data-line="${l.id}" aria-pressed="${l.id===selected}"><span>${l.id}</span><div><b>${esc(l.title)}</b><em>${treeMode==='plan'?'候选':l.closed?'已收束':'推进中'}</em><p>${treeMode==='plan'?`经过第 ${[...new Set(treeChains.filter(c=>c.lineIds.includes(l.id)).map(c=>c.volume))].join('、')} 卷`:esc(l.summary)}</p><small>${esc(l.main)}${treeMode==='actual'&&l.seeds.length?` · ${l.seeds.length}项伏笔未解`:''}</small></div></button>`).join('')||'<p>没有匹配的故事线。</p>'}</div>${lines.length?'<button id="line-detail">查看选中故事详情</button>':''}</aside></div>`;
 $('#volume').value=volumeFocus;$('#main').value=mainFocus;$('#filter').value=filter;
 $('#volume').onchange=e=>{volumeFocus=+e.target.value;zoom=1;dx=dy=0;renderTree()};$('#main').onchange=e=>{mainFocus=e.target.value;renderTree()};$('#filter').onchange=e=>{filter=e.target.value;renderTree()};$('#search').oninput=e=>{query=e.target.value;const p=e.target.selectionStart;renderTree();$('#search').focus();$('#search').setSelectionRange(p,p)};
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{treeMode=b.dataset.mode;filter='all';renderTree()});$('#weave').onclick=()=>{interweave=!interweave;renderTree()};$('#plus').onclick=()=>{zoom=Math.min(3,zoom+.25);transform()};$('#minus').onclick=()=>{zoom=Math.max(.6,zoom-.25);transform()};$('#reset').onclick=()=>{volumeFocus=0;mainFocus='all';query='';filter='all';zoom=1;dx=dy=0;renderTree()};$('#collapse').onclick=()=>{$('.number-list').classList.toggle('is-collapsed');$('#collapse').textContent=$('.number-list').classList.contains('is-collapsed')?'展开':'收起'};
 const activate=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>{b.onclick=()=>fn(b);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn(b)}}});activate('[data-volume]',b=>{volumeFocus=+b.dataset.volume;zoom=1;dx=dy=0;renderTree()});activate('[data-node]',b=>showLine(b.dataset.node,innerWidth<=700));activate('[data-chain]',b=>showChain(b.dataset.chain));activate('[data-line]',b=>showLine(b.dataset.line,false));activate('[data-stop]',b=>{volumeFocus=+b.dataset.stop;renderTree()});if($('#line-detail'))$('#line-detail').onclick=()=>showLine(lines.some(l=>l.id===selected)?selected:lines[0].id,true);
 const svg=$('.canvas svg');let drag=null;svg.onpointerdown=e=>{if(e.target.closest('[role=button]'))return;drag={x:e.clientX,y:e.clientY,dx,dy};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(drag){const s=svg.viewBox.baseVal.width/svg.getBoundingClientRect().width;dx=drag.dx+(e.clientX-drag.x)*s;dy=drag.dy+(e.clientY-drag.y)*s;transform()}};svg.onpointerup=svg.onpointercancel=()=>drag=null;transform();
}
